def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_product_divisibility(n):
    # P(n) is divisible by 11 if and only if at least one S(n+k) is divisible by 11
    # We check n up to 100 as requested.

    for k in range(38):
        m = n + k
        s_m = sum_digits(m)
        if s_m % 11 == 0:
            # Found a factor divisible by 11, so P(n) is divisible by 11
            return True
    # No factor was divisible by 11
    return False

n = 1
while n <= 100:
    if not check_product_divisibility(n):
        print(f"Found the smallest n: {n}")
        break
    n += 1
else:
    print("No such n found up to 100.")

