def check_sequence(n, length=38):
    """Checks if any digit sum in the sequence n, n+1, ..., n+length-1 is a multiple of 11."""
    for i in range(length):
        k = n + i
        if S(k) % 11 == 0:
            return False  # Found a multiple of 11
    return True # All digit sums were NOT multiples of 11

