def check_product(n):
    """Checks if the product S(n)S(n+1)...S(n+37) is divisible by 11."""
    # The product is NOT a multiple of 11 if and only if NONE of the factors are multiples of 11.
    for k in range(38):
        if S(n + k) % 11 == 0:
            return False  # Product is divisible by 11
    return True # Product is NOT divisible by 11

